insert into public.articles (id, drive_file_id, drive_modified_at, title, slug, meta_description, content_type_id, service_area_id, target_keyword, secondary_keywords, tags, author_name, publish_date, body_markdown, status, owner_id, submitted_at, approved_by, approved_at, published_at, published_url, created_at, updated_at) values ('fa7c0821-825c-44b9-92fa-0e53e5c1c3da', 'seed_z4LN6VAW7yKnceVttAfNEjfg5Dfq', '2026-05-08T14:10:30.000Z', 'Industrial Water Engineering on Mining Sites: Common Pitfalls', 'industrial-water-engineering-on-mining-sites-common-pitfalls', 'Industrial water engineering: how industrial water engineering cuts cost and schedule risk on Mining projects in British Columbia.', (select id from public.content_types where slug = 'technical-insight'), (select id from public.service_areas where slug = 'water-management'), 'Industrial water engineering', array['Claims'], array['water-management', 'mining'], 'EPCMst Team', '2026-07-10', 'Vendors respond better when expectations are written down and measured the same way every time. That means naming one accountable person and a clear decision date. Good industrial water engineering is mostly about communication between engineering, procurement and the field. A simple checklist, reviewed at each stage gate, catches most of the issues we see.
insert into public.articles (id, drive_file_id, drive_modified_at, title, slug, meta_description, content_type_id, service_area_id, target_keyword, secondary_keywords, tags, author_name, publish_date, body_markdown, status, owner_id, submitted_at, approved_by, approved_at, published_at, published_url, created_at, updated_at) values ('ae31f229-436b-409c-a153-6ca48f250df8', 'seed_eH9BMDjoTze1XTwBjQCw7a5CskSQ', '2026-06-06T20:07:30.000Z', '5 Lessons on Integrated EPC Delivery from Saskatchewan Projects', '5-lessons-on-integrated-epc-delivery-from-saskatchewan-projects', 'Integrated EPC solutions for Petrochemicals owners in Saskatchewan: where projects go wrong and what good looks like.', (select id from public.content_types where slug = 'technical-insight'), (select id from public.service_areas where slug = 'engineering'), 'Integrated EPC solutions', array['EPC contracting'], array['engineering', 'petrochemicals', 'saskatchewan'], 'EPCMst Team', '2026-06-30', 'When Petrochemicals owners in Saskatchewan search for "Integrated EPC solutions", they usually want one thing: a project that stays on budget and on schedule. On Petrochemicals projects in Saskatchewan, integrated EPC delivery is often decided early and paid for late. Regulators and Indigenous partners expect early, honest engagement, and projects go smoother when they get it. Clear interfaces between contractors prevent the gaps where most rework begins. Our teams have seen the same pattern across several Petrochemicals sites: small gaps early become schedule slips later.
insert into public.articles (id, drive_file_id, drive_modified_at, title, slug, meta_description, content_type_id, service_area_id, target_keyword, secondary_keywords, tags, author_name, publish_date, body_markdown, status, owner_id, submitted_at, approved_by, approved_at, published_at, published_url, created_at, updated_at) values ('211ada74-55dd-4b4d-8011-b3dbfd3baf60', 'seed_Lwqy2v6PcwPcjm7ZoiZuMFchCca1', '2026-03-29T10:53:44.000Z', 'Project Development Plan for BC Projects', 'project-development-plan-for-bc-projects', 'Project development plan: how project development planning cuts cost and schedule risk on Power and Utilities projects in Western Canada.', (select id from public.content_types where slug = 'whitepaper'), (select id from public.service_areas where slug = 'project-management'), 'Project development plan', array['Independent peer review engineering'], array['project-management', 'power and utilities', 'western canada'], 'EPCMst Team', '2026-05-16', 'When Power and Utilities owners in Western Canada search for "Project development plan", they usually want one thing: a project that stays on budget and on schedule. Measuring progress weekly, with the same yardstick, keeps surprises small. Vendors respond better when expectations are written down and measured the same way every time. Cost and schedule risk rarely come from one big decision; they build up from many small ones. Our teams have seen the same pattern across several Power and Utilities sites: small gaps early become schedule slips later.
insert into public.articles (id, drive_file_id, drive_modified_at, title, slug, meta_description, content_type_id, service_area_id, target_keyword, secondary_keywords, tags, author_name, publish_date, body_markdown, status, owner_id, submitted_at, approved_by, approved_at, published_at, published_url, created_at, updated_at) values ('0a94f85b-a84d-4551-bec8-36589a310961', 'seed_RLw2pFgx0UiTBygRbhF63yyy6tY6', '2026-03-09T10:31:05.000Z', 'Case Study: Industrial Water Engineering at a Substation', 'case-study-industrial-water-engineering-at-a-substation', 'Industrial water engineering for Oil and Gas owners in British Columbia: where projects go wrong and what good looks like.', (select id from public.content_types where slug = 'case-study'), (select id from public.service_areas where slug = 'water-management'), 'Industrial water engineering', '{}', array['water-management'], 'EPCMst Team', '2026-04-28', 'When Oil and Gas owners in British Columbia search for "Industrial water engineering", they usually want one thing: a project that stays on budget and on schedule. That means naming one accountable person and a clear decision date. When equipment arrives late, every downstream trade waits, and the camp costs keep running. Good industrial water engineering is mostly about communication between engineering, procurement and the field. Weather, remote access and short construction seasons in British Columbia all raise the stakes.
insert into public.articles (id, drive_file_id, drive_modified_at, title, slug, meta_description, content_type_id, service_area_id, target_keyword, secondary_keywords, tags, author_name, publish_date, body_markdown, status, owner_id, submitted_at, approved_by, approved_at, published_at, published_url, created_at, updated_at) values ('e7977b98-4322-47a9-a10a-cd7cd58e6e11', 'seed_Q9dgmJdbvGtg6mJuzsjXTRAMohCs', '2026-07-05T04:48:03.000Z', '7 Lessons on Independent Peer Review from Northern Alberta Projects', '7-lessons-on-independent-peer-review-from-northern-alberta-projects', 'Independent peer review engineering: how independent peer review cuts cost and schedule risk on Power and Utilities projects in northern Alberta.', (select id from public.content_types where slug = 'technical-insight'), (select id from public.service_areas where slug = 'specialists'), 'Independent peer review engineering', array['Pre-vetted EPCM specialists'], array['specialists', 'power and utilities'], 'EPCMst Team', '2026-08-13', 'When Power and Utilities owners in northern Alberta search for "Independent peer review engineering", they usually want one thing: a project that stays on budget and on schedule. Digital tools help, but only if the people using them trust the information inside. Good independent peer review is mostly about communication between engineering, procurement and the field. That means naming one accountable person and a clear decision date. Regulators and Indigenous partners expect early, honest engagement, and projects go smoother when they get it.
insert into public.articles (id, drive_file_id, drive_modified_at, title, slug, meta_description, content_type_id, service_area_id, target_keyword, secondary_keywords, tags, author_name, publish_date, body_markdown, status, owner_id, submitted_at, approved_by, approved_at, published_at, published_url, created_at, updated_at) values ('7d24b647-28cd-4843-a2f3-8f9440fa0a3b', 'seed_HRTzaycYYQ5cT31dPqsjhXZMJ55j', '2026-07-04T07:50:39.000Z', 'Integrated EPC Solutions for Alberta Projects', 'integrated-epc-solutions-for-alberta-projects', 'Integrated EPC solutions: how integrated EPC delivery cuts cost and schedule risk on Oil and Gas projects in Alberta.', (select id from public.content_types where slug = 'whitepaper'), (select id from public.service_areas where slug = 'engineering'), 'Integrated EPC solutions', array['Structural engineer', 'Calgary engineering company'], array['engineering', 'oil and gas', 'alberta'], 'EPCMst Team', '2026-08-12', 'When Oil and Gas owners in Alberta search for "Integrated EPC solutions", they usually want one thing: a project that stays on budget and on schedule. Lessons learned only count if the next project actually reads them. Vendors respond better when expectations are written down and measured the same way every time. Data from the last turnaround is the best predictor of the next one, if anyone kept it. We recommend a short review at thirty, sixty and ninety percent design for every water treatment plant.
insert into public.articles (id, drive_file_id, drive_modified_at, title, slug, meta_description, content_type_id, service_area_id, target_keyword, secondary_keywords, tags, author_name, publish_date, body_markdown, status, owner_id, submitted_at, approved_by, approved_at, published_at, published_url, created_at, updated_at) values ('6356b403-a34a-4aa0-98d9-cfb158e75684', 'seed_Ki4fDJefX1tEuhHRL9HYH4Y7vqpr', '2026-05-18T07:42:02.000Z', 'Pre Construction on Mining Sites: Common Pitfalls', 'pre-construction-on-mining-sites-common-pitfalls', 'Pre construction: how pre-construction planning cuts cost and schedule risk on Mining projects in Western Canada.', null, null, 'Pre construction', array['Integrated EPC solutions', 'Facilities engineering'], array['construction', 'mining'], 'EPCMst Team', '2026-06-15', 'When Mining owners in Western Canada search for "Pre construction", they usually want one thing: a project that stays on budget and on schedule. Data from the last turnaround is the best predictor of the next one, if anyone kept it. The first step is agreeing what a good outcome looks like before the design is frozen. On Mining projects in Western Canada, pre-construction planning is often decided early and paid for late. Regulators and Indigenous partners expect early, honest engagement, and projects go smoother when they get it.
insert into public.articles (id, drive_file_id, drive_modified_at, title, slug, meta_description, content_type_id, service_area_id, target_keyword, secondary_keywords, tags, author_name, publish_date, body_markdown, status, owner_id, submitted_at, approved_by, approved_at, published_at, published_url, created_at, updated_at) values ('09644b0e-b046-4f3f-b99a-dab46be0724e', 'seed_natbsDEF2jhpEtptNZt1Nxh12T7t', '2026-05-09T14:21:32.000Z', 'Structural Engineer on Petrochemicals Sites: Common Pitfalls', 'structural-engineer-on-petrochemicals-sites-common-pitfalls', 'Practical lessons from Petrochemicals projects in northern Alberta on reducing cost and schedule risk before construction starts.', (select id from public.content_types where slug = 'technical-insight'), (select id from public.service_areas where slug = 'structural-engineering'), 'Structural engineer', '{}', array['structural-engineering'], 'EPCMst Team', '2026-05-28', 'Owners who treat structural engineering as a box to tick usually discover the cost during construction. Weather, remote access and short construction seasons in northern Alberta all raise the stakes. On Petrochemicals projects in northern Alberta, structural engineering is often decided early and paid for late. We recommend a short review at thirty, sixty and ninety percent design for every water treatment plant.
insert into public.articles (id, drive_file_id, drive_modified_at, title, slug, meta_description, content_type_id, service_area_id, target_keyword, secondary_keywords, tags, author_name, publish_date, body_markdown, status, owner_id, submitted_at, approved_by, approved_at, published_at, published_url, created_at, updated_at) values ('2c4389ab-28db-47e1-ae55-bdc4e1219b8a', 'seed_4twZefMweEz07AeoGuZFqej1PMw7', '2026-06-11T19:25:05.000Z', 'Case Study: Agile Project Management at a Substation', 'case-study-agile-project-management-at-a-substation', 'Agile project management for Mining owners in Alberta: where projects go wrong and what good looks like.', (select id from public.content_types where slug = 'case-study'), (select id from public.service_areas where slug = 'project-management'), 'Agile project management', array['Cost control'], array['project-management'], 'EPCMst Team', '2026-08-06', 'When Mining owners in Alberta search for "Agile project management", they usually want one thing: a project that stays on budget and on schedule. On Mining projects in Alberta, agile project management is often decided early and paid for late. Our teams have seen the same pattern across several Mining sites: small gaps early become schedule slips later. The first step is agreeing what a good outcome looks like before the design is frozen. Weather, remote access and short construction seasons in Alberta all raise the stakes.
