insert into public.articles (id, drive_file_id, drive_modified_at, title, slug, meta_description, content_type_id, service_area_id, target_keyword, secondary_keywords, tags, author_name, publish_date, body_markdown, status, owner_id, submitted_at, approved_by, approved_at, published_at, published_url, created_at, updated_at) values ('4b786568-b9d4-4779-8afb-dd2ea70947f2', 'seed_3kpc54mnUyi2JTWq1mhxocy1eynf', '2026-08-31T18:48:16.000Z', 'Case Study: Procurement on an Alberta Upgrader', 'case-study-procurement-on-an-alberta-upgrader', 'Procurement: how procurement cuts cost and schedule risk on Renewables projects in Alberta.', (select id from public.content_types where slug = 'case-study'), (select id from public.service_areas where slug = 'procurement'), 'Procurement', '{}', array['procurement', 'renewables'], 'EPCMst Team', null, 'When Renewables owners in Alberta search for "Procurement", they usually want one thing: a project that stays on budget and on schedule. Regulators and Indigenous partners expect early, honest engagement, and projects go smoother when they get it. Vendors respond better when expectations are written down and measured the same way every time. Clear interfaces between contractors prevent the gaps where most rework begins. Our teams have seen the same pattern across several Renewables sites: small gaps early become schedule slips later.
