insert into public.articles (id, drive_file_id, drive_modified_at, title, slug, meta_description, content_type_id, service_area_id, target_keyword, secondary_keywords, tags, author_name, publish_date, body_markdown, status, owner_id, submitted_at, approved_by, approved_at, published_at, published_url, created_at, updated_at) values ('151c5a52-776e-48db-9ab7-7541e69472db', 'seed_1XBVWQvLoVrtayTRMHRVCVoWXBvh', '2026-08-16T00:01:29.000Z', 'Civil Engineering on Mining Sites: Common Pitfalls', 'civil-engineering-on-mining-sites-common-pitfalls', 'Civil engineering: how civil engineering cuts cost and schedule risk on Mining projects in British Columbia.', (select id from public.content_types where slug = 'technical-insight'), (select id from public.service_areas where slug = 'civil-engineering'), 'Civil engineering', array['Claims'], array['civil-engineering', 'british columbia'], 'EPCMst Team', '2026-09-23', 'When Mining owners in British Columbia search for "Civil engineering", they usually want one thing: a project that stays on budget and on schedule. Good civil engineering is mostly about communication between engineering, procurement and the field. Measuring progress weekly, with the same yardstick, keeps surprises small. On Mining projects in British Columbia, civil engineering is often decided early and paid for late. Data from the last turnaround is the best predictor of the next one, if anyone kept it.
insert into public.articles (id, drive_file_id, drive_modified_at, title, slug, meta_description, content_type_id, service_area_id, target_keyword, secondary_keywords, tags, author_name, publish_date, body_markdown, status, owner_id, submitted_at, approved_by, approved_at, published_at, published_url, created_at, updated_at) values ('843b83d9-0d51-4802-bb47-06e418447ef3', 'seed_7q8U9yMqkFVtKt0hNUKGPvghTLyq', '2026-06-16T13:56:08.000Z', 'Procurement for Northern Alberta Projects', 'procurement-for-northern-alberta-projects', 'Procurement: how procurement cuts cost and schedule risk on Oil and Gas projects in northern Alberta.', (select id from public.content_types where slug = 'whitepaper'), (select id from public.service_areas where slug = 'procurement'), 'Procurement', '{}', array['procurement', 'oil and gas', 'northern alberta'], 'EPCMst Team', '2026-07-07', 'When Oil and Gas owners in northern Alberta search for "Procurement", they usually want one thing: a project that stays on budget and on schedule. Clear interfaces between contractors prevent the gaps where most rework begins. We recommend a short review at thirty, sixty and ninety percent design for every water treatment plant. Data from the last turnaround is the best predictor of the next one, if anyone kept it. When equipment arrives late, every downstream trade waits, and the camp costs keep running.
insert into public.articles (id, drive_file_id, drive_modified_at, title, slug, meta_description, content_type_id, service_area_id, target_keyword, secondary_keywords, tags, author_name, publish_date, body_markdown, status, owner_id, submitted_at, approved_by, approved_at, published_at, published_url, created_at, updated_at) values ('fb9ced2b-3c6f-4cfa-aa17-ad6db4dc28e1', 'seed_e16yt6vb0QXKrfuGiAKyPYUCAuKR', '2026-07-13T01:32:45.000Z', '5 Lessons on Independent Peer Review from Northern Alberta Projects', '5-lessons-on-independent-peer-review-from-northern-alberta-projects', 'Independent peer review engineering: how independent peer review cuts cost and schedule risk on Mining projects in northern Alberta.', (select id from public.content_types where slug = 'technical-insight'), (select id from public.service_areas where slug = 'specialists'), 'Independent peer review engineering', '{}', array['specialists', 'mining', 'northern alberta'], 'EPCMst Team', '2026-08-18', 'Field crews should be involved before drawings are issued for construction, not after. Data from the last turnaround is the best predictor of the next one, if anyone kept it. The cheapest change is the one made on paper; the most expensive is the one made in steel. That means naming one accountable person and a clear decision date.
insert into public.articles (id, drive_file_id, drive_modified_at, title, slug, meta_description, content_type_id, service_area_id, target_keyword, secondary_keywords, tags, author_name, publish_date, body_markdown, status, owner_id, submitted_at, approved_by, approved_at, published_at, published_url, created_at, updated_at) values ('415df934-3727-457d-9643-0b0818d846c4', 'seed_GaMwaLTn8fjYT8SSTsjJPCShnNR0', '2026-06-23T00:28:14.000Z', 'The Case for Integrated EPC Delivery on Renewables Projects', 'the-case-for-integrated-epc-delivery-on-renewables-projects', 'Integrated EPC solutions for Renewables owners in Saskatchewan: where projects go wrong and what good looks like.', (select id from public.content_types where slug = 'technical-insight'), (select id from public.service_areas where slug = 'engineering'), 'Integrated EPC solutions', array['Fractional engineer'], array['engineering', 'renewables'], 'EPCMst Team', '2026-07-23', 'We recommend a short review at thirty, sixty and ninety percent design for every tailings facility. That means naming one accountable person and a clear decision date. Weather, remote access and short construction seasons in Saskatchewan all raise the stakes. Owners who treat integrated EPC delivery as a box to tick usually discover the cost during construction.
insert into public.articles (id, drive_file_id, drive_modified_at, title, slug, meta_description, content_type_id, service_area_id, target_keyword, secondary_keywords, tags, author_name, publish_date, body_markdown, status, owner_id, submitted_at, approved_by, approved_at, published_at, published_url, created_at, updated_at) values ('55243971-7065-4fa6-8602-f73015150a6c', 'seed_mj00pZuXUVcaYTcPsovHiCe4Ud1Z', '2026-05-24T15:21:42.000Z', 'A Practical Guide to Design-Build Delivery in Power and Utilities', 'a-practical-guide-to-design-build-delivery-in-power-and-utilities', 'Design build: how design-build delivery cuts cost and schedule risk on Power and Utilities projects in Alberta.', (select id from public.content_types where slug = 'whitepaper'), (select id from public.service_areas where slug = 'construction'), 'Design build', array['Cost control', 'Engineering consultancy'], array['construction', 'power and utilities', 'alberta'], 'EPCMst Team', '2026-06-17', 'When Power and Utilities owners in Alberta search for "Design build", they usually want one thing: a project that stays on budget and on schedule. Measuring progress weekly, with the same yardstick, keeps surprises small. Cost and schedule risk rarely come from one big decision; they build up from many small ones. Owners who treat design-build delivery as a box to tick usually discover the cost during construction. That means naming one accountable person and a clear decision date.
insert into public.articles (id, drive_file_id, drive_modified_at, title, slug, meta_description, content_type_id, service_area_id, target_keyword, secondary_keywords, tags, author_name, publish_date, body_markdown, status, owner_id, submitted_at, approved_by, approved_at, published_at, published_url, created_at, updated_at) values ('e300731c-ad62-406c-af81-29df8f96a59d', 'seed_DMQDJAovZa4eksUQhcFRWVf2CWTJ', '2026-07-04T12:33:48.000Z', 'Facilities Engineering: Lessons from a Northern Alberta Mill Expansion', 'facilities-engineering-lessons-from-a-northern-alberta-mill-expansion', 'Practical lessons from Renewables projects in northern Alberta on reducing cost and schedule risk before construction starts.', (select id from public.content_types where slug = 'case-study'), (select id from public.service_areas where slug = 'facilities-engineering'), 'Facilities engineering', array['Procurement', 'CAPEX optimization services'], array['facilities-engineering', 'renewables'], 'EPCMst Team', '2026-07-29', 'The first step is agreeing what a good outcome looks like before the design is frozen. Vendors respond better when expectations are written down and measured the same way every time. On Renewables projects in northern Alberta, facilities engineering is often decided early and paid for late. Weather, remote access and short construction seasons in northern Alberta all raise the stakes.
insert into public.articles (id, drive_file_id, drive_modified_at, title, slug, meta_description, content_type_id, service_area_id, target_keyword, secondary_keywords, tags, author_name, publish_date, body_markdown, status, owner_id, submitted_at, approved_by, approved_at, published_at, published_url, created_at, updated_at) values ('4d91ccd9-8ca8-4d4f-b831-0ec308263e97', 'seed_5xWTAi7L5HrVkTNDhJLUP8uG9DeM', '2026-05-26T07:02:23.000Z', 'A Practical Guide to Civil Engineering in Water and Wastewater', 'a-practical-guide-to-civil-engineering-in-water-and-wastewater', 'Civil engineering: how civil engineering cuts cost and schedule risk on Water and Wastewater projects in the Oil Sands region.', (select id from public.content_types where slug = 'whitepaper'), (select id from public.service_areas where slug = 'civil-engineering'), 'Civil engineering', array['Design build'], array['civil-engineering', 'water and wastewater'], 'EPCMst Team', '2026-08-01', 'When Water and Wastewater owners in the Oil Sands region search for "Civil engineering", they usually want one thing: a project that stays on budget and on schedule. That means naming one accountable person and a clear decision date. Cost and schedule risk rarely come from one big decision; they build up from many small ones. Digital tools help, but only if the people using them trust the information inside. Data from the last turnaround is the best predictor of the next one, if anyone kept it.
