insert into public.articles (id, drive_file_id, drive_modified_at, title, slug, meta_description, content_type_id, service_area_id, target_keyword, secondary_keywords, tags, author_name, publish_date, body_markdown, status, owner_id, submitted_at, approved_by, approved_at, published_at, published_url, created_at, updated_at) values ('9458d39c-a196-4e12-9f5e-b74c4611f203', 'seed_t0Nkem0BApxXTCJyMsLMrx0TdjCg', '2026-04-14T02:29:12.000Z', '7 Lessons on Structural Engineering from Northern Alberta Projects', '7-lessons-on-structural-engineering-from-northern-alberta-projects', 'Practical lessons from Power and Utilities projects in northern Alberta on reducing cost and schedule risk before construction starts.', (select id from public.content_types where slug = 'technical-insight'), (select id from public.service_areas where slug = 'structural-engineering'), 'Structural engineer', '{}', array['structural-engineering', 'power and utilities'], 'EPCMst Team', '2026-05-09', 'When Power and Utilities owners in northern Alberta search for "Structural engineer", they usually want one thing: a project that stays on budget and on schedule. We recommend a short review at thirty, sixty and ninety percent design for every pipeline terminal. Our teams have seen the same pattern across several Power and Utilities sites: small gaps early become schedule slips later. Field crews should be involved before drawings are issued for construction, not after. Clear interfaces between contractors prevent the gaps where most rework begins.
